head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.gEmpNo;
scwin.gAcptNo; // 접수번호
scwin.gLdMktTpCd; // 상장공시시장구분
scwin.strSch; // 경과사유
scwin.gDelayTm;
scwin.vScrenID = 'ULDSTF10501.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// 부모창의 데이타 셋팅하기
scwin.fn_setParamData = function() {
    scwin.gEmpNo = js_emp_no; // 세션정보 	

    scwin.gAcptNo = $c.frame.path("../").scwin.gAcptNo;
    scwin.strSch = $c.frame.path("../").gProgRsnCd;
    scwin.gDelayTm = $c.frame.path("../").scwin.gDelayTm;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !X-- > function() {
    var url = "/DisclosureStatus.do?method=readDisclosureDelay&inputMessageId=DSCLDELAYINFO_INOUT" + "&outputMessageId=DSCLDELAYINFO_INOUT" + "&ACPT_NO=" + scwin.gAcptNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DelayInfo.DataID = encodeURI(url);
    dts_DelayInfo.reset();
};




// 경과사유 변경처리하기  
scwin.fn_Modify = function() {
    var vProgRsn = $c.stf.getObjectValue(cmb_ProgRsn);
    if (vProgRsn.length < 1) {
        $c.win.alert("처리지연(경과)유형을 선택하시오.");
        cmb_ProgRsn.focus();
        return;
    }
    if ($c.stf.checkMaxLength(txb_ProgRsn, 200, '경과사유') == false) {
        return;
    }
    dts_ProgRsnInfo.insertRow();
    dts_ProgRsnInfo.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_ProgRsnInfo.setCellData(1, "PROG_RSN_CD", vProgRsn);
    dts_ProgRsnInfo.setCellData(1, "DELAY_TM", scwin.gDelayTm);
    dts_ProgRsnInfo.setCellData(1, "PROG_RSN", $c.stf.getObjectValue(txb_ProgRsn));
    dts_ProgRsnInfo.setCellData(1, "EMP_NO", scwin.gEmpNo);
    var vAnswer = confirm('공시경과사유를 변경하시겠습니까?');
    if (vAnswer == true) {
        trs_ProgRsn.Action = "/DisclosureStatus.do?method=modifyDisclosureDelayReason&inputMessageId=DSCLDELAYINFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_ProgRsn.KeyName = "toinb_dataid4";
        trs_ProgRsn.KeyValue = "JSP(I:pInput=dts_ProgRsnInfo)";
        trs_ProgRsn.Post();
    }
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Modify();
};
scwin.trs_ProgRsn_OnSuccess = async function() {
    $c.win.alert("성공적으로 저장되었습니다.");
    await $c.frame.CloseFrame();

    // 부모창의   reload 처리해야함
    $c.frame.path("../").fn_Search();
};
scwin.trs_ProgRsn_OnFail = function() {
    $c.win.alert('trs_ProgRsn.OnFail() :' + trs_ProgRsn.ErrorMsg);
};
scwin.dts_DelayInfo_OnLoadError = function() {
    $c.stf.alert_error(dts_DelayInfo);
};
scwin.dts_ProgRsn_OnLoadCompleted = function(rowcount) {
    // 초기1회 초기값으로 설정된 사유분류를 검색한다.
    if (scwin.strSch != "") {
        for (var i = 1; i <= dts_ProgRsn.getTotalRow(); i++) {
            if (scwin.strSch == dts_ProgRsn.getCellData(i, 1)) {
                dts_ProgRsn.setRowPosition(i, 0);
                break;
            }
        }
        scwin.strSch = "";
    }
};
scwin.bnt_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(pnl_1);
    scwin.fn_setParamData();

    // 가우스헤더 셋팅
    dts_ProgRsnInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLDELAYINFO_INOUT";
    dts_ProgRsnInfo.reset();

    // 경과사유 리스트  셋팅
    dts_ProgRsn.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=DISCLS_PROG_RSN_CD";
    dts_ProgRsn.Reset();

    // 경과사유 읽어오기
    fn_DelayRead();
};
